#!/usr/bin/env node
// Write boundary for generated documents (P1 safety fix, EB1-C/EB1-F).
//
// Why this exists: `isWriteAllowed()` answers "is this path a normative one?" as a
// STRING, and a string is not a write boundary. `writeFileSync(join(root, target))`
// follows a symlink at the final component and follows a symlinked parent
// directory, so a planted link could send generated bytes into a contract, an agent
// note, or AGENTS.md while every string check still reported "allowed".
//
// The boundary here is real: the location must be in the declared generated area,
// neither the target nor any ancestor below the canonicalised root may be a
// symlink, the walked parent must equal its own realpath, and the open uses
// O_NOFOLLOW.
//
// No CLI on purpose: importing this module must never write anything.

import { constants, existsSync, lstatSync, mkdirSync, openSync, realpathSync, writeSync, closeSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';

/** The only locations this module will ever write. Extending this list is a
 *  deliberate, reviewable expansion of the writable surface. */
export const GENERATED_AREAS = ['dev/engineering'];
export const GENERATED_FILES = ['dev/engineering/current-state.json'];

class Refused extends Error {}

function lstatOrNull(abs) {
  try {
    return lstatSync(abs);
  } catch (e) {
    if (e.code === 'ENOENT') return null;
    throw new Refused(`STAT_ERROR: ${abs}: ${e.code}`);
  }
}

/** Walk `root` -> `rel` refusing any symlink, including the final component when it
 *  already exists. A missing final component is fine: the caller is creating it. */
function assertNoSymlink(root, rel) {
  let cursor = root;
  const parts = rel.split(sep).filter(Boolean);
  for (let i = 0; i < parts.length; i += 1) {
    cursor = join(cursor, parts[i]);
    const st = lstatOrNull(cursor);
    if (!st) {
      if (i !== parts.length - 1) throw new Refused(`MISSING_ANCESTOR: ${cursor} does not exist`);
      return;
    }
    if (st.isSymbolicLink()) {
      throw new Refused(`${i === parts.length - 1 ? 'SYMLINK_TARGET' : 'SYMLINK_ANCESTOR'}: ${cursor}`);
    }
  }
}

/**
 * Write `content` to `rel` inside `root`, or refuse with a reason.
 * Returns { ok:true, path } or { ok:false, why }. A policy refusal never throws, so
 * the caller can print the verdict and exit 2 the way the CLI contract expects.
 */
/** Validate the location without writing. Splitting this out matters: a caller that
 *  compares content first ("already fresh") used to return success without ever
 *  consulting the boundary, so a symlinked target looked fine as long as the bytes
 *  happened to match. */
export function checkGeneratedTarget(root, rel) {
  try {
    if (!GENERATED_AREAS.some((a) => rel === a || rel.startsWith(`${a}/`))) throw new Refused(`NOT_GENERATED_AREA: ${rel}`);
    if (!GENERATED_FILES.includes(rel)) throw new Refused(`NOT_GENERATED_FILE: ${rel}`);

    // The workspace itself may sit under a symlinked mount, so the root is
    // canonicalised once; what has to stay link-free is everything below it.
    const realRoot = realpathSync(root);
    const abs = join(realRoot, rel);
    const within = relative(realRoot, abs);
    if (!within || within === '..' || within.startsWith(`..${sep}`)) throw new Refused(`ESCAPE_ROOT: ${rel} resolves outside ${realRoot}`);

    assertNoSymlink(realRoot, rel);
    const parent = dirname(abs);
    if (existsSync(parent) && realpathSync(parent) !== parent) throw new Refused(`PARENT_NOT_REAL: realpath(${parent}) resolved elsewhere`);
    return { ok: true, realRoot, abs, within };
  } catch (e) {
    return { ok: false, why: e instanceof Refused ? e.message : `IO_ERROR: ${(e && e.message) || String(e)}` };
  }
}

export function writeGenerated(root, rel, content) {
  try {
    const checked = checkGeneratedTarget(root, rel);
    if (!checked.ok) throw new Refused(checked.why);
    const { abs, within } = checked;

    const parent = dirname(abs);
    if (!existsSync(parent)) mkdirSync(parent, { recursive: true });
    if (realpathSync(parent) !== parent) throw new Refused(`PARENT_NOT_REAL: realpath(${parent}) resolved elsewhere`);

    const fd = openSync(abs, constants.O_WRONLY | constants.O_CREAT | constants.O_TRUNC | constants.O_NOFOLLOW, 0o644);
    try {
      writeSync(fd, content);
    } finally {
      closeSync(fd);
    }
    return { ok: true, path: within };
  } catch (e) {
    return { ok: false, why: e instanceof Refused ? e.message : `IO_ERROR: ${(e && e.message) || String(e)}` };
  }
}
